"""Temporary deterministic transport of the locally tested design patch.
Removed with the isolated workbench before merging the reviewed source.
"""
import base64, hashlib, lzma, subprocess
from pathlib import Path
encoded = ''''''
patch=lzma.decompress(base64.b64decode(encoded))
assert hashlib.sha256(patch).hexdigest()=='4ba2d81981dff1662af0be640e8f577236d172ab5e91fdbc371144e1d12ee520', 'Patch integrity check failed'
p=Path('/tmp/ia-design.patch'); p.write_bytes(patch)
args=['git','apply','--unidiff-zero']
if subprocess.run(args+['--reverse','--check',str(p)],capture_output=True).returncode==0:
    print('Reviewed source patch is already present.')
else:
    subprocess.run(args+['--check',str(p)],check=True)
    subprocess.run(args+[str(p)],check=True)
    print('Applied the reviewed source patch; tests and build must pass before commit.')
